from modele import chapitre,E,Q,tableau
from pedagogie import page,bloc

chapitre(13,'angles','Angles et droites parallèles','3 · Espace et géométrie',
'Vocabulaire · Bissectrice · Angles alternes internes et correspondants',
['Reconnaître des angles dans une configuration.','Calculer avec des angles adjacents et opposés.','Utiliser les angles pour caractériser un parallélisme.'],['Rapporteur et angles usuels.'],[
page(1,'Reconnaître les angles',
bloc('definition',r'Un angle nul mesure $0^\circ$, droit $90^\circ$, plat $180^\circ$, plein $360^\circ$. Un angle aigu est strictement compris entre 0 et $90^\circ$ ; un angle obtus entre 90 et $180^\circ$. Dans $\widehat{ABC}$, B est le sommet.'),
r'@FIG:cours-angles@',
bloc('definition',r'Deux angles adjacents ont le même sommet, un côté commun et des intérieurs disjoints. Deux angles supplémentaires ont une somme de $180^\circ$. La bissectrice partage un angle en deux angles de même mesure.'),
bloc('propriete',r'Lorsque deux droites se coupent, deux angles adjacents formant un angle plat ont une somme de $180^\circ$. Deux angles opposés par le sommet ont donc la même mesure : chacun d’eux est supplémentaire d’un même troisième angle, adjacent aux deux.')),
page(2,'Caractériser les parallèles',
r'@FIG:cours-paralleles@',
bloc('definition',r'Une sécante coupe deux droites. Deux angles alternes internes sont entre les droites et de part et d’autre de la sécante. Deux angles correspondants occupent la même position autour des deux intersections.'),
bloc('propriete',r'Si les droites sont parallèles, les angles alternes internes sont égaux, de même que les angles correspondants ; cela se démontre avec le demi-tour (chapitre 15). Réciproquement, l’égalité d’une paire d’angles alternes internes, ou d’une paire d’angles correspondants, prouve le parallélisme ; cette réciproque est admise.'),
bloc('exemple',r'Cas des angles droits : deux droites perpendiculaires à une même droite forment avec elle des angles correspondants droits, donc égaux ; elles sont parallèles. De même, si deux droites sont parallèles, toute perpendiculaire à l’une est perpendiculaire à l’autre.'),
bloc('savoirfaire',r'Identifier d’abord la paire d’angles. Écrire l’hypothèse connue : droites parallèles ou égalité des angles. Choisir la propriété dans le bon sens puis conclure. Une ressemblance sur le dessin ne suffit pas.','Aller des données à la conclusion'))
],[
E('Nommer un angle',r'Dans la figure, quel est le sommet de $\widehat{AOB}$ ? L’angle de $40^\circ$ est-il aigu ?',r'Le sommet est la lettre du milieu, $\res O$. Comme $0<40<90$, l’angle est $\res{aigu}$.','Lire la notation et la mesure.','assert 0<40<90',figure='ang-1'),
E('Un angle droit partagé',r'Un angle droit est partagé en deux angles de $35^\circ$ et $x$. Calculer $x$.',r'Le total vaut $90^\circ$, donc $x=90-35=\res{55^\circ}$.','Utiliser la mesure de l’angle total.','assert 90-35==55',figure='ang-2'),
E('Un angle plat partagé',r'Deux angles adjacents forment un angle plat. L’un mesure $128^\circ$. Calculer l’autre.',r'Ils sont supplémentaires : $180-128=\res{52^\circ}$.','Compléter jusqu’à 180 degrés.','assert 180-128==52',figure='ang-3'),
E('Opposés par le sommet',r'Deux droites se coupent. Un angle vaut $63^\circ$. Que vaut l’angle opposé par le sommet ?',r'Les angles opposés par le sommet sont égaux : $\res{63^\circ}$.','Reconnaître la paire.','assert 63==63',figure='ang-4'),
E('Bissectrice',r'La demi-droite verte est la bissectrice d’un angle de $74^\circ$. Quelle mesure a chaque moitié ?',r'Les deux mesures sont égales et totalisent $74^\circ$ : $74:2=\res{37^\circ}$.','Partager l’angle en deux parts égales.','assert 74//2==37',figure='ang-5'),
E('Quatre angles autour d’un point',r'Deux droites se coupent et un angle vaut $47^\circ$. Donner les trois autres mesures.',r'L’opposé vaut $47^\circ$. Les deux adjacents valent $180-47=133^\circ$. Les quatre mesures alternent $\res{47,133,47,133}$.','Combiner opposition et supplémentarité.','assert 180-47==133 and 2*(47+133)==360',figure='ang-6'),
E('Alternes internes',r'Les droites $(d)$ et $(e)$ sont parallèles. L’angle marqué $a$ est alterne interne avec l’angle de $68^\circ$. Calculer $a$.',r'Les droites sont parallèles, donc les angles alternes internes sont égaux : $\res{a=68^\circ}$.','Vérifier la position de la paire.','assert 68==68',figure='ang-7'),
E('Correspondants',r'Les droites sont parallèles et deux angles correspondants sont marqués. L’un vaut $112^\circ$. Trouver l’autre.',r'Des angles correspondants découpés par une sécante sur deux parallèles sont égaux : $\res{112^\circ}$.','Identifier des positions correspondantes.','assert 112==112',figure='ang-8'),
E('Prouver un parallélisme',r'Les deux angles alternes internes indiqués mesurent chacun $72^\circ$. Que peut-on conclure sur les droites ?',r'Les angles alternes internes sont égaux. Par la propriété réciproque, les deux droites sont $\res{parallèles}$.','Partir de l’égalité des angles.','assert 72==72',figure='ang-9'),
E('Exclure un parallélisme',r'Deux angles correspondants mesurent $75^\circ$ et $78^\circ$. Les droites peuvent-elles être parallèles ?',r'Non : si elles étaient parallèles, ces angles seraient égaux. Comme $\res{75\ne78}$, elles ne sont pas parallèles.','Utiliser une condition nécessaire.','assert 75!=78',figure='ang-10'),
E('Deux étapes',r'Les droites sont parallèles. Au premier croisement, un angle obtus vaut $124^\circ$. Trouver l’angle aigu indiqué au second croisement.',r'Au premier croisement, l’angle adjacent aigu vaut $180-124=56^\circ$. Son correspondant au second croisement vaut donc $\res{56^\circ}$.','Compléter puis transporter un angle.','assert 180-124==56',figure='ang-11'),
E('Équerres',r'On utilise une équerre de $30^\circ$, $60^\circ$, $90^\circ$ et une de $45^\circ$, $45^\circ$, $90^\circ$. En juxtaposant un angle de $30^\circ$ et un de $45^\circ$, obtenir la mesure totale puis son supplément.',r'Le total vaut $30+45=\res{75^\circ}$. Son supplément vaut $180-75=\res{105^\circ}$.','Additionner des angles adjacents.','assert 30+45==75 and 180-75==105',figure='ang-12'),
E('Un angle à reconstituer',r'Autour de O, trois angles consécutifs valent $110^\circ$, $95^\circ$ et $x$. Le dernier vaut $80^\circ$. Trouver $x$.',r'Un tour complet vaut $360^\circ$. Donc $x=360-110-95-80=\res{75^\circ}$. Contrôle : les quatre angles totalisent 360 degrés.','Utiliser le tour complet.','assert 360-110-95-80==75',figure='ang-13'),
E('Justifier sans mesurer',r'Les droites $(d)$ et $(e)$ sont toutes deux perpendiculaires à la sécante, comme l’indique le codage. Une élève affirme qu’elles sont parallèles « parce qu’on le voit à la règle ». Proposer une justification correcte.',r'Une impression ou une mesure ne prouve pas. Les deux angles correspondants codés sont droits, donc égaux à $90^\circ$. Par la propriété réciproque, $\res{(d)\parallel(e)}$ : deux droites perpendiculaires à une même droite sont parallèles.','Citer la donnée et la propriété.','assert 90==90 and 180-90==90',figure='ang-14'),
E('Une bissectrice dans des parallèles',r'Les droites sont parallèles. Un angle au premier croisement vaut $106^\circ$. Au second, on partage l’angle aigu correspondant en deux par une bissectrice. Trouver chaque moitié.',r'L’angle aigu vaut $180-106=74^\circ$. Le parallélisme conserve cette mesure au second croisement. La bissectrice donne $74:2=\res{37^\circ}$ par moitié.','Enchaîner supplément, correspondance et partage.','assert (180-106)//2==37',figure='ang-15')
],reperes=['Vocabulaire et angles usuels','Adjacents, opposés, supplémentaires, bissectrice','Angles avec des parallèles','Réciproques et raisonnement'],deco='geometrie')

chapitre(14,'triangles','Construire et comprendre les triangles','3 · Espace et géométrie',
'Angles · Médiatrices · Cercle circonscrit · Hauteurs · Médianes',
['Construire un triangle à partir de données.','Tracer hauteurs, médianes et médiatrices.','Calculer des aires et expliquer une preuve.'],['Angles, compas, règle et équerre.'],[
page(1,'Angles et construction',
bloc('propriete',r'La somme des angles d’un triangle est $180^\circ$. Pour le voir, tracer par un sommet la parallèle au côté opposé : les angles alternes internes reportent les deux autres angles à ce sommet, où ils forment ensemble un angle plat.'),
r'@FIG:cours-triangle-angles@',
bloc('savoirfaire',r'On peut construire un triangle avec trois longueurs, deux côtés et l’angle compris, ou un côté et deux angles. Avec trois côtés, tracer d’abord un segment puis deux arcs de compas. Pour un triangle non aplati, le plus grand côté doit être strictement inférieur à la somme des deux autres.','Choisir les instruments'),
bloc('exemple',r'4, 5 et 7 cm permettent un triangle car $7<4+5$. 2, 3 et 6 cm ne le permettent pas car $6>2+3$.')),
page(2,'Médiatrices et cercle circonscrit',
bloc('definition',r'La médiatrice d’un segment est la droite perpendiculaire à ce segment passant par son milieu. Ses points sont à égale distance des deux extrémités, et tout point équidistant des extrémités appartient à la médiatrice.'),
r'@FIG:cours-cercle-circonscrit@',
bloc('propriete',r'Les trois médiatrices d’un triangle sont concourantes. Leur point commun O est équidistant des trois sommets ; il est le centre du cercle circonscrit. Pour construire O, deux médiatrices suffisent ; on contrôle avec le troisième sommet.'),
bloc('savoirfaire',r'Dans un triangle isocèle, la droite du sommet principal au milieu de la base est un axe de symétrie : elle porte la médiatrice de la base, la hauteur et la médiane correspondantes. Dans un équilatéral, cette propriété vaut aux trois sommets.','Triangles particuliers'),
bloc('propriete',r'Dans un triangle rectangle, on observe que le centre du cercle circonscrit est le milieu de l’hypoténuse, le côté opposé à l’angle droit : le triangle est inscrit dans un demi-cercle dont l’hypoténuse est un diamètre. Cette propriété est admise en Cinquième ; elle sera démontrée en Quatrième.')),
page(3,'Tracer les hauteurs',
bloc('definition',r'Une hauteur est une droite passant par un sommet et perpendiculaire à la droite qui porte le côté opposé. Pour calculer une aire, on utilise aussi la longueur du segment perpendiculaire entre le sommet et cette droite.'),
r'@FIG:cours-hauteurs@',
bloc('propriete',r'Les trois hauteurs sont concourantes en un point appelé orthocentre ; cette propriété, constatée sur des figures, est admise. Il est à l’intérieur pour un triangle aigu, au sommet de l’angle droit pour un triangle rectangle et à l’extérieur pour un triangle obtus.'),
bloc('attention',r'Une hauteur peut rencontrer le prolongement d’un côté. La médiane et la médiatrice ne sont pas définies par la même condition : la hauteur exige la perpendicularité, pas le milieu.')),
page(4,'Aires et médianes',
bloc('propriete',r'L’aire d’un triangle est $A=\frac{b\times h}{2}$, où $h$ est la hauteur relative à la base $b$. Convertir les longueurs dans la même unité avant de calculer.'),
r'@FIG:cours-mediane@',
bloc('definition',r'Une médiane est la droite passant par un sommet et par le milieu du côté opposé. Le segment joignant ces deux points partage le triangle en deux triangles d’aires égales : leurs bases ont la même longueur et ils ont la même hauteur. On observe que les trois médianes sont concourantes, en un point appelé centre de gravité ; cette propriété est admise.'),
bloc('exemple',r'Pour une base de 8 cm et une hauteur de 3 cm, l’aire vaut $8\times3:2=12$ cm$^2$. La médiane issue du sommet correspondant donne deux aires de 6 cm$^2$.'),
bloc('attention',r'Dans un triangle quelconque, une médiane n’est pas nécessairement perpendiculaire au côté. Un schéma codé donne les hypothèses ; l’apparence ne constitue pas une preuve.'))
],[
E('Troisième angle',r'Deux angles d’un triangle mesurent $48^\circ$ et $67^\circ$. Calculer le troisième.',r'La somme vaut $180^\circ$ : $180-48-67=\res{65^\circ}$.','Compléter la somme des trois angles.','assert 180-48-67==65',figure='tri-1'),
E('Un isocèle',r'ABC est isocèle en A et $\widehat A=44^\circ$. Calculer les angles en B et C.',r'Les angles à la base sont égaux. Ils totalisent $180-44=136^\circ$, donc chacun vaut $136:2=\res{68^\circ}$.','Partager le reste entre deux angles égaux.','assert (180-44)//2==68',figure='tri-2'),
E('Une construction à trois côtés',r'Construire ABC avec $AB=6$ cm, $AC=4$ cm et $BC=5$ cm.',r'Tracer AB de 6 cm. Tracer un arc de centre A et de rayon 4 cm, puis un arc de centre B et de rayon 5 cm. Une intersection donne C ; relier. Il y a deux positions symétriques par rapport à (AB).','Croiser deux arcs de compas.','assert 6<4+5 and abs(4-5)<6',figure='tri-3'),
E('Aire directe',r'Un triangle a une base de 9 cm et une hauteur correspondante de 4 cm. Calculer son aire.',r'$A=9\times4:2=\res{18\ \mathrm{cm}^2}$. Base et hauteur correspondent à un même sommet et à son côté opposé.','Associer la bonne base et la bonne hauteur.','assert Rational(9*4,2)==18',figure='tri-4'),
E('Reconnaître une médiane',r'M est le milieu de [BC]. Pourquoi (AM) est-elle une médiane du triangle ABC ?',r'Elle joint le sommet A au milieu du côté opposé [BC]. C’est exactement la définition d’une $\res{médiane}$. Aucune perpendicularité n’est nécessaire.','Utiliser le milieu indiqué.','assert Rational(6,2)==3',figure='tri-5'),
E('Deux côtés et un angle',r'Construire $AB=5$ cm, $AC=3$ cm et $\widehat{BAC}=60^\circ$.',r'Tracer AB. En A, tracer une demi-droite formant $60^\circ$ avec [AB). Y reporter 3 cm pour C, puis tracer [BC]. L’angle est construit au sommet A.','Placer l’angle entre les côtés connus.','assert 0<60<180 and 5>0 and 3>0',figure='tri-6'),
E('Un côté et deux angles',r'Construire $AB=6$ cm, $\widehat{BAC}=50^\circ$ et $\widehat{ABC}=60^\circ$. Calculer $\widehat C$.',r'Tracer AB puis les demi-droites faisant 50 degrés en A et 60 degrés en B, dans le même demi-plan. Leur intersection est C. Le dernier angle vaut $180-50-60=\res{70^\circ}$.','Construire les angles aux bonnes extrémités.','assert 180-50-60==70',figure='tri-7'),
E('Hauteur extérieure',r'Dans le triangle obtus donné, tracer la hauteur issue de C relative à (AB). Pourquoi faut-il prolonger [AB] ?',r'Le pied H de la perpendiculaire se trouve au-delà de B. On prolonge la droite (AB), puis on trace la perpendiculaire à (AB) passant par C. Une hauteur porte sur la droite du côté, pas seulement sur le segment.','Chercher une perpendiculaire au support.','assert (8-6)>0 and (8-8)==0',figure='tri-8'),
E('Cercle circonscrit',r'Construire le cercle passant par les trois sommets du triangle donné.',r'Tracer les médiatrices de [AB] et [AC]. Leur intersection O vérifie $OA=OB$ et $OA=OC$, donc les trois distances sont égales. Tracer le cercle de centre O passant par A ; il passe aussi par B et C.','Trouver un point équidistant des trois sommets.','assert Rational(3)**2+Rational(1)**2==10',figure='tri-9'),
E('Hauteur et aire',r'Un triangle a une aire de 24 cm$^2$ et une base de 8 cm. Trouver la hauteur correspondante.',r'$8h:2=24$, donc $4h=24$ et $h=\res{6\ \mathrm{cm}}$. On peut aussi doubler l’aire puis diviser par la base.','Retrouver un facteur de la formule.','assert Rational(2*24,8)==6',figure='tri-10'),
E('Aire et médiane',r'ABC a une aire de 35 cm$^2$ et M est le milieu de [BC]. Calculer les aires de ABM et ACM en justifiant.',r'Les bases BM et MC ont la même longueur et les triangles ont la même hauteur issue de A. Leurs aires sont égales et totalisent 35 cm$^2$ : chacune vaut $\res{17{,}5\ \mathrm{cm}^2}$.','Comparer bases et hauteurs.','assert Rational(35,2)==Rational("17.5")',figure='tri-11'),
E('Triangle rectangle : hauteurs et cercle',r'ABC est rectangle en A. Identifier deux de ses hauteurs et le point de concours des trois hauteurs. Construire ensuite le cercle circonscrit à ABC : où se trouve son centre ?',r'(AB) et (AC), perpendiculaires, sont les hauteurs issues de B et de C ; l’orthocentre est $\res A$. Les médiatrices de [AB] et [AC] se coupent en O, $\res{milieu\ de\ [BC]}$ : c’est le centre du cercle circonscrit.','Repérer les perpendiculaires déjà présentes.','assert 3*0+0*4==0 and all((px-Rational(3,2))**2+(py-2)**2==Rational(25,4) for px,py in [(0,0),(3,0),(0,4)])',figure='tri-12'),
E('Un isocèle et ses droites',r'ABC est isocèle en A et M est le milieu de [BC]. Expliquer pourquoi (AM) est à la fois médiane, médiatrice de [BC] et hauteur. Pourquoi le centre du cercle circonscrit appartient-il à (AM) ?',r'C’est une médiane par définition de M. L’axe de symétrie du triangle isocèle passe par A et M ; il est perpendiculaire à (BC). C’est donc aussi la médiatrice de [BC] et la hauteur issue de A. Le centre du cercle circonscrit appartient à toutes les médiatrices, donc en particulier à \res{(AM)}.','Exploiter la symétrie d’un triangle particulier.','assert (3-0)**2+4**2==(3-6)**2+4**2',figure='tri-13'),
E('Un tracé impossible',r'Peut-on construire un triangle de côtés 3 cm, 4 cm et 8 cm ? Et de côtés 3, 4 et 7 cm ?',r'Pour 3, 4 et 8 : $3+4<8$, donc impossible. Pour 3, 4 et 7 : $3+4=7$, les points sont alignés, le triangle est aplati. Aucun des deux n’est un triangle non aplati.','Comparer le plus grand côté à la somme des deux autres.','assert 3+4<8 and 3+4==7',figure='tri-14'),
E('Deux bases pour la même aire',r'ABC a $AB=12$ cm, la hauteur issue de C vaut 5 cm et $BC=10$ cm. Trouver la hauteur issue de A puis l’aire de chaque triangle créé par la médiane issue de C.',r'L’aire vaut $12\times5:2=\res{30\ \mathrm{cm}^2}$. Avec la base BC, $10h:2=30$, donc $h=\res6$ cm. La médiane issue de C partage l’aire en deux : $\res{15\ \mathrm{cm}^2}$ chacune.','Calculer une aire commune avant de changer de base.','assert Rational(12*5,2)==30 and Rational(2*30,10)==6 and 30//2==15',figure='tri-15')
],reperes=['Angles et constructions de triangles','Médiatrices et cercle circonscrit','Hauteurs et concours','Aires, médianes et triangles particuliers'],deco='geometrie')
